    private val aliases = mapOf("book" to "book-open", "code" to "code-xml", "work" to "briefcase-business", "home" to "house", "sport" to "dumbbell", "food" to "utensils", "travel" to "plane", "game" to "gamepad-2", "plant" to "sprout", "lab" to "flask-conical", "chat" to "messages-square")
    private val cache = mutableMapOf<String, ImageVector>()
    fun image(key: String): ImageVector = cache.getOrPut(key) {
        val resolved = aliases[key] ?: key
        ImageVector.Builder(key, 24.dp, 24.dp, 24f, 24f, autoMirror = key in listOf("arrow-left", "chevron-left", "chevron-right"))
            .addPath(pathData = PathParser().parsePathString(paths[resolved] ?: paths.getValue("shapes")).toNodes(),
                stroke = SolidColor(Color.Black), strokeLineWidth = 1.8f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round).build()
    }
    val icons by lazy {
        val original = listOf("book", "code", "coffee", "star", "work", "music", "home", "heart", "sport", "food", "travel", "camera", "game", "plant", "lab", "chat")
        (original + paths.keys.filter { it !in original && it !in aliases.values }).map { it to image(it) }
    }
}